/// The emoji for a shortcode name (without colons), if it's one we know.
pub fn emoji(name: &str) -> Option<&'static str> {
    CODES.binary_search_by(|(n, _)| (*n).cmp(name)).ok().map(|i| CODES[i].1)
}

/// `text` with every known `:shortcode:` as its emoji. Unchanged text comes
/// back borrowed.
pub fn shortcodes(text: &str) -> Cow<'_, str> {
    if !text.contains(':') {
        return Cow::Borrowed(text);
    }
    let mut out = String::new();
    let mut done = 0;
    let mut i = 0;
    let b = text.as_bytes();
    while i < b.len() {
        if b[i] == b':' {
            // The name runs to the next colon: letters, digits, _ + -.
            let start = i + 1;
            let end = b[start..]
                .iter()
                .position(|c| !(c.is_ascii_lowercase() || c.is_ascii_digit() || matches!(c, b'_' | b'+' | b'-')))
                .map_or(b.len(), |n| start + n);
            if end > start && end < b.len() && b[end] == b':' {
                if let Some(e) = emoji(&text[start..end]) {
                    out.push_str(&text[done..i]);
                    out.push_str(e);
                    done = end + 1;
                    i = end + 1;
                    continue;
                }
            }
        }
        i += 1;
    }
    if done == 0 {
        return Cow::Borrowed(text);
    }
    out.push_str(&text[done..]);
    Cow::Owned(out)
}

/// Markdown with its shortcodes as emoji, leaving code alone: fenced blocks
/// and `inline code` keep theirs, so a snippet that means `:x:` still says so.
pub fn shortcodes_markdown(md: &str) -> Cow<'_, str> {
    if !md.contains(':') {
        return Cow::Borrowed(md);
    }
    let mut out = String::with_capacity(md.len());
    let mut fenced = false;
    for line in md.split_inclusive('\n') {
        if line.trim_start().starts_with("```") {
            fenced = !fenced;
            out.push_str(line);
            continue;
        }
        if fenced {
            out.push_str(line);
            continue;
        }
        // Odd pieces between backticks are code.
        for (n, piece) in line.split('`').enumerate() {
            if n > 0 {
                out.push('`');
            }
            if n % 2 == 1 {
                out.push_str(piece);
            } else {
                out.push_str(&shortcodes(piece));
            }
        }
    }
    if out == md { Cow::Borrowed(md) } else { Cow::Owned(out) }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn codes_are_sorted() {
        assert!(CODES.windows(2).all(|w| w[0].0 < w[1].0), "CODES must stay sorted for the binary search");
    }

    #[test]
    fn known_codes_turn_into_emoji() {
        assert_eq!(shortcodes(":sparkles: New Features"), "✨ New Features");
        assert_eq!(shortcodes(":bug: Bug Fixes and :wrench: Chores"), "🐛 Bug Fixes and 🔧 Chores");
        assert_eq!(shortcodes(":+1::tada:"), "👍🎉");
    }

    #[test]
    fn other_colons_stay() {
        assert_eq!(shortcodes("at 10:30:45"), "at 10:30:45");
        assert_eq!(shortcodes(":not_a_code: x"), ":not_a_code: x");
        assert_eq!(shortcodes("https://a.b:8080/c"), "https://a.b:8080/c");
        assert_eq!(shortcodes("Note: ok :Sparkles:"), "Note: ok :Sparkles:");
        assert!(matches!(shortcodes("plain"), Cow::Borrowed(_)));
    }

    #[test]
    fn markdown_keeps_code() {
        let md = "## :sparkles: New\n- `:bug:` stays, :bug: goes\n```\n:fire:\n```\n:fire:";
        assert_eq!(
            shortcodes_markdown(md),
            "## ✨ New\n- `:bug:` stays, 🐛 goes\n```\n:fire:\n```\n🔥"
        );
    }
}
